package com.example.activite.web.controller;
import com.example.activite.domain.Paiement; import com.example.activite.service.IPaiementService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.Parameter; import io.swagger.v3.oas.annotations.responses.*; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/paiements") @RequiredArgsConstructor @Tag(name="Paiements",description="Consultation des paiements") public class PaiementController { private final IPaiementService paiementService;
@GetMapping @Operation(summary="Lister les paiements") @ApiResponse(responseCode="200",description="Liste retournée") public List<Paiement> findAll(){return paiementService.findAll();}
@GetMapping("/{id}") @Operation(summary="Consulter un paiement") @ApiResponses({@ApiResponse(responseCode="200",description="Paiement trouvé"),@ApiResponse(responseCode="404",description="Paiement introuvable")}) public Paiement findById(@Parameter(description="Identifiant du paiement") @PathVariable Long id){return paiementService.findById(id);}}
